import { VEHICLES, VEHICLE_BY_ID, SOURCES, SOURCE_NOTES } from './vehicles.js?v=1.15.0';
import { UPGRADE_SOURCES } from './upgrades.js?v=1.15.0';

const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
const number = (value, digits = 0) => Number(value).toLocaleString('en-US', { maximumFractionDigits: digits });
const resolveVehicle = selected => typeof selected === 'object' && selected?.engine && VEHICLE_BY_ID[selected.id] ? selected : VEHICLE_BY_ID[typeof selected === 'string' ? selected : selected?.id] || VEHICLES[0];
const keys = values => values.map(value => `<kbd>${escapeHTML(value)}</kbd>`).join('');
const keyRow = (values, description) => `<div class="guide-keyrow"><span>${keys(values)}</span><span>${description}</span></div>`;
const table = (headings, rows) => `<table><thead><tr>${headings.map(heading => `<th scope="col">${heading}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map((cell, index) => index === 0 ? `<th scope="row">${cell}</th>` : `<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table>`;

function selectedControls(vehicle) {
  if (vehicle.transmissionType === 'electric') return `
    <h3>Your HUMMER EV SUV 3X</h3>
    <p>This is the 2024 SUV with the Extreme Off-Road Package: three motors, fixed front and rear reductions, 35-inch mud-terrain tires and independent air suspension. Select <strong>D</strong> to drive and <strong>R</strong> for manual reverse. There is no low-range transfer case.</p>
    ${table(['Control', 'How it works here'], [
      ['Four-wheel steer · Auto', 'Rear wheels turn opposite the fronts at low speed and transition toward the same direction around 25 mph. All four physical tire directions change; the system does not directly rotate the chassis.'],
      ['CrabWalk', 'Stop and center the wheels, then select CrabWalk. All four wheels turn together up to 10 degrees for diagonal travel below 20 mph. Rear steering transitions out above that range; sustained speed over 25 mph for 10 seconds restores Auto.'],
      ['Rear steer · Off', 'Stop, center the steering, and select P or N before switching Off. Select D afterward. Auto can be restored from the selector.'],
      ['Air suspension', 'Normal, Increased (+46 mm) and Extract (+149 mm) adjust the actual air-spring target progressively. Extract requires Terrain mode, centered steering and less than 12 mph. The vehicle is speed-limited while at Extract height.'],
      ['Front / rear locks', 'The rear is a virtual lock between its two motors. Normal-mode cutoff is 25 mph; Terrain and Off-Road allow up to 50 mph. The front mechanical locker requires Terrain mode, automatically engages the rear lock, and releases above 15 mph. Front locking automatically suspends ABS until it releases.'],
      ['One-Pedal Driving', 'Releasing the accelerator requests motor regeneration, followed by low-speed brake hold. Terrain mode also applies lift-off braking. The brake pedal remains available.'],
      ['Regen on Demand', 'Hold B or the Regen on Demand button to request stronger regenerative braking. Release to let go. The live value reports estimated recovered power.'],
      ['Watts to Freedom', 'Stop in Drive with unlocked axles and CrabWalk off. Enable the feature, wait for lowering, center the wheels and hold S/brake, then add full W/accelerator. Release S/brake while keeping W held to launch. Small steering corrections retain launch output. A substantial turn, braking, lifting, loss of ground support or the launch timeout ends the peak boost and enters standby with normal accelerator and steering control. Stop, center the wheels and repeat the brake/accelerator sequence for another launch. Disable the feature to restore normal height.'],
    ])}
    <p>The published <strong>830 hp</strong> and <strong>11,500 lb-ft at the wheels</strong> are separate limits. Wheel torque already includes reduction gearing. The estimated three-motor envelope applies those reductions once. Normal mode uses an estimated reduced peak-torque envelope; the launch sequence unlocks the short-duration peak. Battery thermal preparation, charge depletion, full stability-control firmware and factory infotainment are outside this model. The 51 mm launch lowering is a shared-platform estimate.</p>`;
  if (vehicle.upgrade?.build.drivetrain === 'conversion' && vehicle.bodyStyle === 'sedan') return `
    <h3>Your converted Civic</h3><p>The custom simulated AWD conversion retains the CVT and front open differential, adding a rear driveline and controlled center coupling. Select <strong>FWD</strong> for front drive or <strong>4A</strong> for automatic rear assistance. The estimated coupling sends up to 45% of engine torque rearward as demand rises. There is no low range or axle locker.</p><p>Added hardware changes mass, static axle loading and drivetrain losses. ECON, Normal and Sport retain their estimated pedal and CVT maps. This is a custom simulation build, not a factory Civic option or a verified bolt-on conversion.</p>`;
  if (vehicle.upgrade?.build.drivetrain === 'conversion' && vehicle.bodyStyle === 'van') return `
    <h3>Your converted Sprinter</h3><p>The generic 4×4 build adds a driven front axle, a part-time transfer case and a rear locker. <strong>2H</strong> drives the rear wheels; <strong>4H</strong> couples both axles; <strong>4L</strong> adds <strong>2.50:1</strong> reduction. Stop and select <strong>N</strong> before changing into or out of low range.</p><p>Request the rear locker below about 10 km/h in 4H or 4L. It releases above about 30 km/h and re-engages below 10 km/h if still requested. The conversion includes an 80 mm minimum suspension lift and estimated additional hardware mass. It preserves the mechanical rear parking brake. This is a simulated custom build, not a factory equipment claim.</p>`;
  if (vehicle.id === 'wrangler-rubicon') return `
    <h3>Your Wrangler Rubicon</h3>
    <p><strong>2H</strong> drives the rear axle. <strong>4H</strong> couples the front and rear axles. <strong>4L</strong> adds a 4.00:1 transfer reduction. This configuration has the part-time Rock-Trac transfer case.</p>
    ${table(['Control', 'How it works here'], [
      ['Rear / front locks', 'Select 4L and slow below 10 mph. Lock the rear before the front. Opening the rear also opens the front. Requested locks release above 30 mph and re-engage below 10 mph.'],
      ['Stabilizer disconnect', 'Available in 4H or 4L below 18 mph. It removes the front anti-roll coupling. A requested disconnect reconnects above 18 mph and disconnects again below 14 mph.'],
      ['Hill Descent Control', 'Requires 4L. With the accelerator released on a forward or reverse descent, it applies braking to limit speed.'],
      ['Off Road+', 'Available in 4H or 4L. In this build it permits more wheel slip before traction control reduces engine torque or brakes a spinning wheel. It does not reproduce every factory throttle, shift and stability-control map.'],
    ])}
    <p>The factory rear-locker exception for 4H with Off Road+ and ESC fully off is outside the current control model. Use 4L for either locker in this build.</p>`;
  if (vehicle.id === 'bronco-badlands') return `
    <h3>Your Bronco Badlands</h3>
    <p><strong>2H</strong> drives the rear axle. <strong>4A</strong> varies front-axle assistance with throttle and rear-wheel slip. <strong>4H</strong> couples both axles; <strong>4L</strong> adds a 3.06:1 transfer reduction.</p>
    ${table(['Control', 'How it works here'], [
      ['Rear / front locks', 'The rear is available in 2H, 4A, 4H or 4L; the front requires 4L. Normally, request a lock below 20 mph; it releases above 25 mph and returns below 20 mph. The rear speed restriction is lifted in 4L and in Mud/Ruts, Sand, Rock Crawl or Baja.'],
      ['Stabilizer disconnect', 'Available in 4H or 4L below 20 mph. A requested disconnect reconnects above 20 mph and returns below that threshold.'],
      ['Trail Control', 'A simplified low-speed cruise controller adds throttle or braking toward the selected trail speed. Select D or R, keep the engine running and release the brake.'],
      ['Trail Turn Assist', 'Requires 4H or 4L and an open rear differential. At low speed and a large steering angle it brakes the inside rear wheel. Turn this off before requesting a rear lock.'],
      ['Trail One-Pedal Drive', 'Requires 4H or 4L. Releasing the accelerator adds braking. The response is an approximation of the factory system.'],
    ])}
    <p>This automatic Badlands uses the 2.7 V6. Trail Control supplies its low-speed speed assistance; a separate manual-transmission Hill Descent Control button is not fitted. Enabling Trail Control switches off Trail One-Pedal Drive, and enabling One-Pedal switches off Trail Control.</p>
    <h3>G.O.A.T. driving programs</h3>
    <p>The program selector applies estimated pedal, automatic-shift and traction-control maps. It also requests the transfer setting below. If a change enters or leaves 4L, first stop and select Neutral; return to Drive after the program is selected.</p>
    ${table(['Program / requested drive mode', 'Estimated response'], [
      ['Normal / Eco · 2H', 'Normal is the baseline. Eco softens partial-pedal response and favors earlier part-throttle upshifts.'],
      ['Slippery · 4A', 'Softer pedal response and a lower wheel-slip threshold for traction control.'],
      ['Mud/Ruts / Sand · 4H', 'More direct partial-pedal response, later part-throttle upshifts and more permitted wheel slip.'],
      ['Rock Crawl · 4L', 'A gentler initial pedal response and low transfer gearing for slow progress.'],
      ['Baja · 4H', 'A more direct partial-pedal response, later part-throttle upshifts and a higher traction-control slip threshold.'],
    ])}
    <p>Programs preserve the selected build’s engine curve. Traction control can reduce delivered torque when the tires spin, even at full pedal. Programs do not change the soil’s grip or supply extra horsepower. Set axle locks and stabilizer disconnect yourself; a transfer-mode change can clear incompatible settings. The complete factory software and its automatic feature sequences are not reproduced.</p>`;
  if (vehicle.id === 'civic-sport') return `
    <h3>Your Civic Sport</h3>
    <p>The Civic drives its <strong>front wheels</strong> through an open differential and a continuously variable transmission. The ratio varies between 2.526:1 and 0.408:1 in forward drive, so the gear display reads <strong>CVT</strong>.</p>
    <p>Traction control and ABS are active initially. There is no transfer range, axle locker or stabilizer disconnect on this configuration. Its shorter tire sidewalls and estimated lower clearance make suspension travel and underbody contact especially visible on the rough sections.</p>
    <p>The program selector offers <strong>ECON, Normal and Sport</strong> with estimated pedal and CVT response maps. ECON softens partial-pedal response and favors lower engine speeds; Sport responds more directly and holds a higher CVT target at partial throttle. Full pedal requests the selected build’s engine output, including installed Workshop engine parts; traction control can reduce delivered torque when the front tires spin. Paddle-selected simulated steps are outside the current transmission-control model.</p>`;
  return `
    <h3>Your Sprinter 2500 Crew</h3>
    <p>This 2016 standard-roof, 144-inch-wheelbase configuration drives its <strong>rear wheels</strong> through a five-speed automatic and an open rear differential. ${vehicle.upgrade?.build.engine !== 'stock' && vehicle.upgrade ? 'The engine follows the selected Workshop torque curve.' : 'The engine model follows the factory 325 lb-ft torque plateau from 1,400 to 2,400 rpm.'}</p>
    <p>Traction assistance and ABS are active initially. Traction assistance can reduce engine torque and brake an excessively spinning driven wheel. This RWD configuration has no 4×4 transfer case, low range, axle locker or stabilizer disconnect. The longer wheelbase, higher estimated center of gravity and commercial tires affect its progress over the same route.</p>
    <p>The vehicle represents the specified Sprinter type; its load, options, pressure setup and handling have not been calibrated to an individual van.</p>`;
}

function controls(vehicle) {
  return `
    <h3>Start driving</h3>
    <p>Close the guide and click the 3D view to give the driving controls focus. ${vehicle.transmissionType === 'electric' ? 'The electric drive starts ready' : 'The engine starts running'} with Drive selected. Use the garage to change vehicle and the terrain list to jump to a destination.</p>
    <div class="guide-keygrid">
      ${keyRow(['W', '↑'], 'Accelerate; stop reversing, then return to Drive')}
      ${keyRow(['S', '↓'], 'Brake; keep holding after stopping to reverse')}
      ${keyRow(['A', 'D'], 'Steer left / right; arrow keys also work')}
      ${keyRow(['R'], 'Select manual Reverse after stopping')}
      ${keyRow(['F'], 'Select Drive after stopping')}
      ${keyRow(['N'], 'Select Neutral')}
      ${keyRow(['P'], 'Select Park after stopping')}
      ${keyRow(['Space'], 'Hold the parking / emergency brake; release to let go')}
      ${vehicle.features.regenOnDemand ? keyRow(['B'], 'Hold the HUMMER EV Regen on Demand paddle') : ''}
      ${keyRow(['G'], 'Open Winch: fit a kit and select a tree anchor')}
      ${keyRow(['E', 'Q'], 'Hold to reel winch cable in / pay out')}
      ${keyRow(['X'], 'Recover to a settled starting position')}
      ${keyRow(['C'], 'Cycle Chase, Hood, Orbit and Free cameras')}
      ${keyRow(['H'], 'Toggle headlights')}
      ${keyRow(['I'], vehicle.transmissionType === 'electric' ? 'Enable / disable electric drive outside Free camera' : 'Start / stop the engine outside Free camera')}
      ${keyRow(['Esc'], 'Pause / resume, or close an open dialog')}
      ${keyRow(['?'], 'Open this guide')}
    </div>
    <div class="guide-callout"><strong>Hold to reverse:</strong> hold <kbd>S</kbd> or the brake control to stop. After a brief pause at a standstill, the transmission selects Reverse and the same held control backs you up. Release to stop applying power. Hold <kbd>W</kbd> or the accelerator to brake while reversing, then return to Drive once stopped. This also works with touch pedals and gamepad triggers.</div>
    <p>Manual selection is still available. Press <kbd>R</kbd> after stopping to use conventional reverse controls: <kbd>W</kbd> accelerates backward and <kbd>S</kbd> only brakes. Press <kbd>F</kbd> for Drive to restore automatic direction selection. Neutral and Park stay selected until you change them. Holding both pedals or the parking brake cancels a pending automatic direction change.</p>
    <h3>Camera, touch &amp; gamepad</h3>
    <p>In <strong>Orbit</strong>, drag to look around the vehicle. In <strong>Free</strong>, use <kbd>I</kbd><kbd>J</kbd><kbd>K</kbd><kbd>L</kbd> to move horizontally and <kbd>U</kbd><kbd>O</kbd> for altitude. The propulsion on/off shortcut is suspended in Free camera. On touch screens, use the on-screen steering, accelerator and brake controls.</p>
    ${table(['Standard gamepad', 'Action'], [
      ['Left stick', 'Steer left / right'], ['Right trigger / left trigger', 'Forward / brake, then reverse after stopping'], ['B / Y / A', 'Hold emergency brake / cycle camera / recover'], ['D-pad up / down', 'Hold winch reel in / pay out'], ['Left bumper / right bumper', 'Select manual Reverse / Drive after stopping'],
    ])}
    <p>Gamepad steering can be enabled in Settings. Button labels follow the standard browser gamepad layout; the symbols on a particular controller can differ.</p>
    <h3>Parking / emergency brake</h3>
    <p>Hold <kbd>Space</kbd>, the touch <strong>E-BRAKE</strong> button, or gamepad <strong>B</strong>. Releasing the control releases the simulated brake. The HUD identifies the active mode. The transmission’s <strong>P</strong> selector is a separate control.</p>
    <p><strong>Wrangler and Sprinter:</strong> a mechanical rear parking brake can stop rear wheel rotation, consume rear cornering grip and let the rear end slide. The front wheels keep rolling unless the service brake or another fitted assist also acts on them. <strong>Civic, Bronco and HUMMER EV:</strong> the held electronic switch requests controlled emergency braking while moving, then rear holding near rest. The Civic’s manual specifies all-wheel VSA braking; dynamic axle distribution for the Bronco and HUMMER EV is estimated. The HUMMER EV front-locker interlock can suspend ABS.</p>
    ${vehicle.parkingBrake ? `<div class="guide-callout"><strong>${escapeHTML(vehicle.name)} · ${escapeHTML(vehicle.parkingBrake.control)}.</strong> ${escapeHTML(vehicle.parkingBrake.calibrationStatus)}</div>${vehicle.parkingBrake.sources.map(sourceEntry).join('')}` : ''}
    <h3>Winch recovery</h3>
    <p>Open <strong>Winch</strong> in the vehicle console, use the toolbar button or press <kbd>G</kbd>. Stop and choose <strong>Fit recovery winch</strong>. The front-mounted kit is optional aftermarket equipment, saved separately for each vehicle and shown on its garage model.</p>
    <ol><li>Point the front bumper toward a standing tree within roughly <strong>24 m</strong>. The nearby recovery trees at Rutted Hollow are a useful starting point.</li><li>Select a tree in the list. A ground ring marks it. Choose <strong>Attach cable</strong>; the wire rope connects to a trunk strap through a shackle.</li><li>Hold <kbd>E</kbd> or <strong>Reel in</strong> to take up slack and pull. Ease off the vehicle brakes; you can steer and apply gentle throttle while winching.</li><li>Release the remote to stop the motor and hold deployed rope length. Hold <kbd>Q</kbd> or <strong>Pay out</strong> to release more cable. Choose <strong>Detach</strong> when clear.</li></ol>
    <p>The cable exerts force at the front fairlead, so an angled pull can rotate or tilt the chassis. Motor speed decreases with load and the motor can stall. A fallen anchor, an obstructed cable, an extreme rearward pull or a severe overload releases the line. Recovery, vehicle changes, terrain travel and restart also detach it. Opening a dialog, pausing or losing focus stops the held controls.</p>
    <h3>Garage, paint &amp; repair</h3>
    <p>The garage shows isolated views of the actual driving models. Drag a model to rotate it, use the rotate button, or focus the model and use the arrow keys. <kbd>Home</kbd> resets its view. Choose a paint swatch or a custom color; colors are saved separately for each vehicle and applied when you drive.</p>
    <p>The garage shows a pristine display model and reports the vehicle’s saved condition. Driving damage persists when you change vehicles or recover. Open <strong>Condition</strong> in the vehicle console to inspect bodywork, ${vehicle.transmissionType === 'electric' ? 'electric drive units' : 'engine'}, suspension and tires. Stop, then choose <strong>Repair vehicle</strong> to restore it. Critical damage disables propulsion until you repair or restart.</p>
    <p><strong>Recover</strong> puts a vehicle upright and retains damage. <strong>Restore undisturbed terrain</strong> clears tracks and ruts. <strong>Restart run</strong> repairs the selected vehicle, returns it to the current terrain’s starting point, and restores the ground and damaged scenery. Saved paint and display settings stay in place.</p>
    <h3>Transfer range &amp; vehicle controls</h3>
    ${vehicle.driveModes.includes('4L') ? '<div class="guide-callout"><strong>To use 4 Low:</strong> slow to a stop, select <kbd>N</kbd>, choose <strong>4L</strong> in Drivetrain, then select <kbd>F</kbd> for Drive. Use Neutral again before leaving 4L. The simulator rejects transfer-range changes above 3 mph (about 5 km/h).</div>' : `<div class="guide-callout">The selected ${escapeHTML(vehicle.name)} build has no low-range transfer case.</div>`}
    <p>Controls appear for the selected vehicle’s equipment. A rejected request leaves the setting unchanged and shows the reason. Changing to an incompatible drive mode clears its locks, stabilizer disconnect and associated assists. Requested locks or disconnects can change state automatically with speed; amber “Armed” means the request is retained while the hardware has temporarily released or reconnected. Click its switch again to cancel that pending request.</p>
    ${selectedControls(vehicle)}
    <h3>Tire setup &amp; live data</h3>
    <p><strong>Workshop</strong> in the navigation or on a garage card opens the upgrade builder. ${vehicle.transmissionType === 'electric' ? 'Choose tire construction, wheel size and suspension parts. The HUMMER EV retains its factory electric power module and e4WD units.' : 'Choose tire construction, wheel size, engine, suspension and drivetrain parts.'} The preview uses the same configured model as the driving vehicle, and the comparison shows output, mass, geometry and gearing. Choose <strong>Install build</strong> while the active vehicle is stopped. <strong>Restore factory build</strong> prepares the factory choices; install them to remove upgrades. Paint, winch choice and damage remain separate.</p>
    <p>Open <strong>Tires</strong> to change front and rear pressures from 8–80 PSI. Uncheck <strong>Link front &amp; rear</strong> for independent axle settings. Road, Trail and Soft ground are convenient simulated setups. The footprint indicator reports the estimated front-left contact area from loaded tire geometry. Tire flattening and sidewall bulge change with pressure, wheel load and support under the contact patch.</p>
    <p>Open <strong>Live data</strong> to compare each wheel’s surface, contact load and slip as you drive. <strong>Peak tire grip use</strong> shows the most heavily used contact’s available tire force; near 100%, adding acceleration or braking leaves less capacity for cornering. <strong>TC torque reduction</strong> shows how much requested ${vehicle.transmissionType === 'electric' ? 'motor' : 'engine'} torque the traction controller is withholding. A spinning wheel can have high wheel speed while the vehicle barely moves; an airborne wheel has no ground grip.</p>
    <p>Pressure adjustment is an instant setup tool. None of these configurations has a factory central tire inflation system. The presets are simulator setup controls. ABS is normally active; the HUMMER EV front-locker interlock can suspend it automatically.</p>
    <h3>Summit Challenge Park</h3>
    <p>Select <strong>Summit Challenge Park</strong> in the terrain list or map. The starting lane leads along a 238 m run-up into a 40 m loop. The exit is offset from the entrance. The separate lanes contain a tabletop, a 10 m gap jump, a narrow balance ramp, alternating articulation wedges and slalom blocks.</p>
    <p>Build speed along the full runway, follow the lane center, and release the accelerator as the loop starts climbing. Look ahead through the turn; the exit moves sideways from the entry. The loop uses the same three-dimensional surface for tire support and solid collision. Gravity, suspension and available grip determine whether you stay in contact. Insufficient speed can make the vehicle fall from the loop; jumps contain real unsupported gaps. Repair or restart is available after a failed attempt.</p>`;
}

function technique(vehicle) {
  return `
    <h3>Run a useful comparison</h3>
    <p>Pick one vehicle and a short, repeatable line. Begin with its Road pressure preset, open axle differentials and the default drive mode. Keep weather and entry speed the same, change one setting, and watch the live wheel data as well as the vehicle’s progress.</p>
    <p>Mud, marsh and sand retain deep ruts; hardpack, gravel and grass retain shallow tread impressions. Rolling over soil compacts it, while spinning or sliding tires also churn it. A used line can therefore behave differently on the next pass. For a fair repeat, open <strong>Settings → Restore undisturbed terrain</strong>, or use a fresh strip alongside the previous run. Recover repositions the vehicle; restoring terrain clears the grooves and their disturbance history.</p>
    ${table(['Destination', 'Try this in the simulator'], [
      ['Tarmac Straight · paved road', 'Compare acceleration and braking with the road setup. Make a slow circle in 2H, then compare 4H and axle locks where available. Coupling wheel speeds increases tire scrub during a turn. Repeat with rain to see the lower modeled grip.'],
      ['Pine Ridge Trail · hardpack / gravel / grass', 'The brown packed center responds more firmly than its loose gravel shoulders. The grassy verge offers less grip, especially in rain. Cross a shoulder gradually and watch each wheel’s surface label; contact patches can span two materials. Firm ground leaves shallow impressions, capped at 12 mm. The Tires panel separates ground rut depth from tire flex.'],
      ['Granite Steps · rock', 'Approach the ledges slowly in 4L if fitted. Compare open axles with a rear lock, then front and rear locks. Disconnect the front stabilizer and watch left/right load differences as the wheels cross different heights. The short-clearance Civic and long Sprinter expose different underbody-contact limits.'],
      ['Rutted Hollow · mud', 'Drive one pass with smooth throttle, then deliberately add more wheelspin on a fresh line. Sliding and spinning churn the mud, reduce its modeled strength and deepen the grooves. Rut walls can resist sideways motion even when tire friction is low. Compare open differentials, traction control and available lockers while watching which wheels remain loaded.'],
      ['Willow Marsh · wet ground', 'Follow a shallow crossing and compare the speed lost to low soil grip, sinkage and water drag. The water-depth readout describes the simulated ground below the vehicle. It is not a manufacturer wading-depth rating.'],
      ['Copper Dunes · loose sand', 'Compare the Road and Soft ground setups on the same dune at the same entry speed. Lower modeled pressure enlarges the footprint and reduces the pressure-driven sinkage term, while also changing rolling resistance and steering response. Sand resists rolling and can build up beside a sliding tire. Rain represents damp, unsaturated sand here, with modestly firmer support; flooded sand is not modeled.'],
    ])}
    <h3>What the main adjustments change</h3>
    <p><strong>Workshop parts</strong> change the physical setup. Road tires trade soft-ground bite for firmer steering response; open-lug tires trade road precision and rolling efficiency for soil traction. Larger tires change radius, width, rotational inertia and effective gearing. A spring kit changes free length, stiffness, damping, travel and anti-roll response. Engine packages alter the torque curve; more torque can produce wheelspin when the surface cannot support it. Added driven axles share propulsion across more contact patches while adding hardware mass and driveline loss.</p>
    <p><strong>Steering and sliding</strong> depend on turn radius and lateral acceleration as well as speed. Keyboard and touch steering have a progressive range and finite slew suitable for binary inputs; an analog stick retains direct full-range control with a finer center. Tire forces build over a rolling relaxation length. Sustained sliding reduces available tire friction by a material-dependent amount, and grip recovers as slip falls. Acceleration, braking and cornering share that contact limit. Fast entries, throttle, braking, wetness and loose soil can still make the vehicle slide or roll.</p>
    <p><strong>Low range</strong> multiplies wheel torque and reduces road speed for a given engine speed. It helps meter a slow climb; the tire-ground force still has a grip limit. ${vehicle.driveModes.includes('4L') ? `The selected ${escapeHTML(vehicle.name)} build has a first-gear reduction of <strong>${number(vehicle.gears[0] * vehicle.finalDrive * vehicle.lowRatio, 1)}:1</strong> in 4L, including the installed axle gearing.` : `The selected ${escapeHTML(vehicle.name)} build has no low-range transfer case.`}</p>
    <p><strong>Axle locks</strong> constrain left and right wheel rotation together. They help when one side loses support or traction, and create more scrub when the wheels need to travel different distances around a turn. In 4H / 4L, the transfer case also constrains average front and rear shaft speed. Bronco 4A uses a simplified variable torque split.</p>
    <p><strong>Stabilizer disconnect</strong> removes the modeled front anti-roll load coupling. Compare wheel contact on cross-axle ledges and body roll in a turn. The amount of movement is controlled by estimated springs, damping and travel.</p>
    <p><strong>Tire pressure</strong> changes the estimated loaded radius, footprint, grip response, rolling resistance and soft-ground sinkage. More grip is not guaranteed at every pressure on every surface. The model favors pressure near the baseline on firm ground and gives a flotation benefit from lower pressure on soft ground.</p>
    <p><strong>Traction control</strong> reduces drive torque when driven tires spin excessively and can brake a wheel that spins faster than its axle partner. It restores requested torque progressively as grip returns. Its slip allowance depends on the surface and driving program, so loose-ground programs permit more wheelspin. The controller acts through propulsion and wheel torque. A mechanical locker couples the two wheel speeds; the HUMMER EV rear virtual lock coordinates its two rear motors. <strong>ABS</strong> reduces brake torque when needed to keep a wheel rolling; it does not increase tire-ground grip.</p>
    <p><strong>Driving programs</strong> on the Bronco and Civic adjust estimated pedal response, shift or CVT behavior and permitted wheel slip. Compare them at partial throttle, where the response maps differ most. Bronco programs can also request a different transfer mode; use Neutral for a change into or out of Rock Crawl / 4L. The HUMMER EV uses estimated motor response, traction, regenerative braking and air-height maps; Watts to Freedom has a separate launch sequence. Full pedal requests the selected build’s available propulsion output, subject to the active mode, traction intervention and mechanical condition.</p>
    <div class="guide-callout"><strong>Current setup: ${escapeHTML(vehicle.name)}.</strong> Available drive modes: ${vehicle.driveModes.map(escapeHTML).join(', ')}. Current tire size: ${escapeHTML(vehicle.tireSize)}. Pressure presets are experiments inside this simulation; actual vehicle pressures depend on the tire, rim, axle load and manufacturer instructions.</div>
    <h3>Read a failed climb</h3>
    <p>If wheel speed rises without forward progress, reduce the accelerator and compare slip and contact load. If the center of the body rests on a crest, more wheel torque may only deepen the ruts: try a different line or recover. If engine speed falls while the tires remain planted, compare a lower transfer range where fitted. Use the same line to separate gearing, grip and clearance effects.</p>`;
}

function physics() {
  return `
    <h3>A physical prototype with visible assumptions</h3>
    <p>The vehicle uses a six-degree-of-freedom rigid chassis, four wheel contact probes and independently integrated wheel rotation. The physics runs at a fixed <strong>120 Hz</strong>; rendering quality changes the view, not that update rate. Tire forces act at the contact points, so acceleration, braking and uneven ground produce body pitch, roll and load transfer.</p>
    <div class="guide-callout">Factory peak power, peak torque and documented gearing anchor the vehicle data. The HUMMER EV’s advertised torque is measured after reduction gearing; its motor-shaft torque is estimated separately. Full engine and motor curves, chassis coefficients, tire behavior and soil parameters are estimates. This build has not been validated against manufacturer handling tests or instrumented real-vehicle measurements.</div>
    ${table(['Subsystem', 'Implemented behavior'], [
      ['Combustion engine &amp; transmission', 'Combustion vehicles use interpolated torque curves anchored to published torque and horsepower peaks. Automatic gear selection, estimated torque-converter multiplication, drivetrain loss and engine braking turn engine output into axle torque. The Civic uses a continuous forward CVT ratio.'],
      ['Electric motors &amp; regeneration', 'The HUMMER EV uses separate front and rear fixed reductions with one front and two rear motors. Each motor has an estimated constant-torque / constant-power envelope bounded by the published combined power and wheel-torque claims. Reductions are applied once, with no torque converter or automatic gear changes. One-Pedal Driving, Terrain lift-off and held Regen on Demand request motor braking, with a low-speed service-brake hold. Recovered power is estimated; battery charge and thermal limits are not simulated.'],
      ['Drive layout &amp; differentials', 'FWD, RWD and four-wheel drive send torque to the specified axles. Open mechanical axle differentials receive equal drive torque on each side. Locks constrain wheel angular speeds. Part-time 4H / 4L couples front and rear shaft speeds; Bronco 4A uses an estimated on-demand front torque share. HUMMER EV e4WD has a front mechanical differential and independent rear motors with a virtual rear lock; it has no center propshaft or transfer case.'],
      ['Suspension &amp; body contact', 'Per-wheel spring and damper forces, finite travel, progressive bump resistance and front/rear anti-roll coupling support the chassis. A fitted front stabilizer disconnect removes the front coupling. HUMMER EV air-height settings progressively change the physical spring target; its body rises through suspension force. Underbody and roof contact samples resist penetration and allow high-centering or a rollover.'],
      ['Tire grip', 'Small-slip stiffness, peak friction, sliding friction and rolling resistance vary independently by material. Rolling carcass relaxation and coupled longitudinal/lateral demand produce transient grip and sliding. A weighted footprint blends contact properties at material edges. Pressure, tire package, load and damage change the response. Excess demand can saturate tires and unload the inside wheels.'],
      ['Vehicle upgrades', 'Fresh configured specifications drive both physics and rendering. Tires change contact coefficients, radius, width and rotational inertia. Compatible combustion-engine packages change the torque curve. Suspension changes free length, spring/damper/anti-roll rates and travel. Available conversions change driven axles, transfer gearing, hardware mass, weight distribution and driveline loss. The HUMMER EV retains its factory power and e4WD modules.'],
      ['Inflation pressure', 'Pressure and carcass stiffness determine loaded radius and contact geometry. The visible tire flattens near support, spreads its sidewalls and follows a small sampled terrain profile; rims remain rigid. The same pressure, load and footprint feed the soil model.'],
      ['Impact damage', 'Normal impact speed, contact location and estimated energy accumulate local dents and mechanical damage. Bodywork, propulsion units, suspension and tires retain their condition. Severe damage disables propulsion. Trees and scenery respond to the corresponding impact events.'],
      ['Rollover &amp; emergency brake', 'Tire contact forces and obstacle impacts act on the six-degree-of-freedom chassis. Rapid direction changes, high center of gravity, cross-slopes or sideways obstacle strikes can cause a tip or rollover. Mechanical rear parking brakes can lock rear wheels; electronic emergency braking uses a separate modeled control path.'],
      ['Winch recovery', 'A finite tension-only cable pulls at the front fairlead each physics substep. The motor winds the drum at load-dependent speed; its spring brake holds cable length when released. A fixed standing tree receives the opposite load and bends slightly. There is no recovery teleport during winching.'],
      ['Driving aids &amp; programs', 'Traction control combines a propulsion-torque reduction with selective wheel braking. ABS and fitted descent / trail assists request or reduce brake torque. Bronco and Civic programs alter estimated pedal, transmission and traction-control maps. HUMMER EV programs control estimated motor response, regeneration and air height; Auto rear steer and CrabWalk change the four physical tire directions. Off Road+ increases the slip allowance. Trail Turn Assist brakes the inside rear wheel in a tight, slow turn. These are behavioral approximations, not factory control software.'],
      ['Terrain &amp; weather', 'Pavement, hardpack, gravel, grass, rock, mud, marsh and sand have separate estimated responses. Moisture, compaction and churning affect each material differently. Soil resists a translating tire, including when it is locked, and buried edges encounter extra sideways resistance. Rain also slightly changes water depth. Wind, hydrology and drying are not simulated.'],
    ])}
    <h3>Research behind the handling model</h3>
    <p>Published experiments inform the mechanisms and their scale. Tire-rig measurements show finite, load-dependent cornering-force response; soft-soil tests show pressure and wheel slip changing traction and sinkage. Grass braking measurements also show why a wet grassy shoulder cannot share hardpack grip. These sources do not provide measured force tables for the exact catalogue tires, so the installed coefficients remain estimates.</p>
    <div class="source-entry"><span class="source-label">Tire-rig experiments</span><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC9459800/" target="_blank" rel="noopener noreferrer">Alcázar Vargas et al. · Tire lateral dynamics and relaxation ↗</a></div>
    <div class="source-entry"><span class="source-label">Soft-soil experiments</span><a href="https://vtechworks.lib.vt.edu/items/167607e6-71f1-4b5c-bce9-9e8678ef2fbe" target="_blank" rel="noopener noreferrer">Virginia Tech · Instrumented off-road tire traction and sinkage ↗</a></div>
    <div class="source-entry"><span class="source-label">Grass braking experiments</span><a href="https://saferroadsconference.com/wp-content/uploads/2016/05/Peter-Cenek-Frictional-Characteristics-Roadside-Grass-Types.pdf" target="_blank" rel="noopener noreferrer">Cenek, Jamieson and McLarin · Roadside grass friction ↗</a></div>
    <div class="source-entry"><span class="source-label">Factory traction-assist behavior</span><a href="https://www.mbvans.com/content/dam/mb-vans/us/cloudinary/mercedes-benz-vans/manuals/2016/2016-Sprinter-Owners-Manual.pdf" target="_blank" rel="noopener noreferrer">Mercedes-Benz · 2016 Sprinter manual, ASR engine and wheel-brake intervention ↗</a></div>
    <div class="source-entry"><span class="source-label">Tire-model methodology</span><a href="https://api.chrono.projectchrono.org/wheeled_tire.html" target="_blank" rel="noopener noreferrer">Project Chrono · Transient handling models and their validation limits ↗</a></div>
    <div class="source-entry"><span class="source-label">Soil-force mechanisms</span><a href="https://help.altair.com/2024/hwdesktop/hwx/topics/motionview/soft_soil_tire_r.htm" target="_blank" rel="noopener noreferrer">Altair · Tire shear, compaction resistance and side bulldozing ↗</a></div>
    <div class="source-entry"><span class="source-label">Chassis compliance study</span><a href="https://www.nhtsa.gov/sites/nhtsa.gov/files/nadstreadsepreport_final_300dpi.pdf" target="_blank" rel="noopener noreferrer">NHTSA DOT HS 809 523 · Simulated SUV understeer and tire failure ↗</a></div>
    <h3>How the ground deforms</h3>
    <p>Dirt, grass and soft soil use local detail tiles created where tires travel, with <strong>0.1 m</strong> detail spacing. A swept tire footprint joins successive contacts into continuous grooves. Load, actual footprint pressure, inflation pressure, wheel slip, speed, compaction and the soil type affect sinkage. Repeated passes can deepen existing ruts, while lower pressure spreads the load across a wider, longer patch.</p>
    <p>The rendered surface and contact queries read the same deformed heights. Displaced soil forms side shoulders and small piles ahead of rolling tires; driven slip also carries spoil off the trailing edge. Sand spreads into broader banks, while fresh snow mainly compresses. Full receiving shoulders redirect soil into available space, and compacted tread marks change the surface color and detail. Compaction and churning are stored separately: packing granular soil can firm it, while shearing wet mud weakens it and increases resistance. Soil resistance acts on a tire moving through the ground even when its rotation is locked. Existing rut depth also affects the sideways soil force on a buried tire edge. Tracks and their material history persist through vehicle changes and recovery until the ground is restored or the run is restarted.</p>
    <p>Trail edges, grass, pavement, rock, sand, mud, marsh and snow have distinct surface treatments. Firm dirt and grass compress into shallow tread impressions, while mud, sand and marsh deform more deeply. Pavement and rock remain rigid. The Tires panel shows the deepest ground rut and greatest tire flex beneath the tires currently in contact. Water adds approximate drag and capped buoyancy.</p>
    <h3>How damage works</h3>
    <p>Damage uses collision events and excessive landing loads. Local impacts dent and scuff the body; damage near glass or lights can mark or break their visible surfaces. The mechanical condition model can reduce propulsion output, alter suspension and alignment, and damage tires. The Condition panel shows the retained state.</p>
    <p>Tree impacts produce damped trunk/canopy motion and persistent visible scars; harder impacts can damage trees and signs further. Object responses depend on their type. Recovering the vehicle does not clear scenery damage. Repair restores only the selected vehicle; Restart run also restores the scene.</p>
    <h3>What has not been modeled</h3>
    <p><strong>Tires:</strong> load-dependent deformation and sampled support are approximations. A full finite-element carcass, tire temperature, measured tire-specific force datasets and complete bead-unseating behavior are outside this model.</p>
    <p><strong>Suspension:</strong> each wheel is supported by suspension contact probes. Separate unsprung rigid bodies, complete axle-linkage constraints and multidirectional bushing models are outside the current model. Springs, dampers, lateral-force steering compliance and damage response use estimated parameters. Tires follow the sampled ground and rock surface. Finite tread and track-shoe contacts support tires on fallen logs and boards; side contacts and the chassis also meet their finite obstacle geometry.</p>
    <p><strong>Soil and water:</strong> soil is an empirical deformable height field with estimated compaction and berm displacement. It does not resolve individual soil particles, full volumetric mud flow, hydrology or real-world terramechanics calibration. Water ingestion and hydrolock are not modeled.</p>
    <p><strong>Crashes:</strong> visible dents and mechanical damage follow estimated impact energy and location. They do not constitute a structural crash solver or predict the outcome of a real collision. Repair is an instant simulator action.</p>
    <p><strong>Winch:</strong> rated first-layer pull, steel rope diameter and total rope length follow the <a href="https://www.warn.com/products/vr-evo-12-winch-103254" target="_blank" rel="noopener noreferrer">WARN VR EVO 12 specifications</a>: 12,000 lb / 53.4 kN, 9.5 mm wire rope and 25.9 m of cable. Usable reach is 24.5 m with a retained drum reserve. Cable compliance, the load/speed curve, drum-layer pull reduction and overload response are estimates. The mounts are simulation accessories; battery drain, accessory mass, motor heating, moving anchors, pulleys and cable wrapping around obstacles are outside this model.</p>
    <p><strong>Factory systems and appearance:</strong> G.O.A.T. and ECON / Sport use estimated response maps; complete factory control software, all dashboard functions and every manufacturer interlock are not reproduced. Gear shifts, stability assistance and trail assists are simplified. Vehicles use parametric 3D approximations, not licensed manufacturer CAD models. The garage notes distinguish the exact configuration choices and carry-over or estimated specifications.</p>
    <p>Use the proving ground to explore how these modeled mechanisms interact. Its acceleration, stopping distances, rut depths and pressure results should be treated as prototype outputs, not predictions of an individual real vehicle.</p>`;
}

function sourceEntry(id) {
  const source = SOURCES[id];
  if (!source) return '';
  return `<div class="source-entry"><span class="source-label">${escapeHTML(source.kind)}</span><a href="${escapeHTML(source.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(source.title)} ↗</a></div>`;
}

function sources(vehicle) {
  const orderedVehicles = [vehicle, ...VEHICLES.filter(candidate => candidate.id !== vehicle.id)];
  const torqueRPM = vehicle.engine.peakTorqueRPMRange ? vehicle.engine.peakTorqueRPMRange.map(value => number(value)).join('–') : number(vehicle.engine.peakTorqueRPM);
  return `
    <h3>${escapeHTML(vehicle.year)} ${escapeHTML(vehicle.name)}</h3>
    <p>${escapeHTML(vehicle.trim)}. Source documents below identify the factory reference configuration. Manufacturer-authored documents on an archive are labeled; carry-over specifications are explicitly identified.</p>
    ${vehicle.upgrade?.count ? `<div class="guide-callout"><strong>${escapeHTML(vehicle.upgrade.label)}.</strong> The table shows the installed build. Generic package outputs and masses are estimates. Factory reference trim: ${escapeHTML(vehicle.factoryTrim)}.</div>` : ''}
    ${table(['Specification', vehicle.upgrade?.count ? 'Installed build value' : 'Catalogue value'], [
      [vehicle.transmissionType === 'electric' ? 'Combined motor power' : 'Peak engine power', `${number(vehicle.powerHP)} hp${vehicle.transmissionType === 'electric' ? ' · GM-estimated peak' : ` at ${number(vehicle.engine.peakPowerRPM)} rpm`}`],
      [vehicle.transmissionType === 'electric' ? 'Combined wheel torque' : 'Peak engine torque', vehicle.transmissionType === 'electric' ? `${number(vehicle.wheelTorqueLbFt)} lb-ft / ${number(vehicle.wheelTorqueNm)} N·m · after drive reductions` : `${number(vehicle.torqueLbFt)} lb-ft / ${number(vehicle.torqueNm)} N·m at ${torqueRPM} rpm`],
      ['Simulation mass', `${number(vehicle.mass)} kg · ${escapeHTML(vehicle.massStatus)}`],
      ['Wheelbase / tire size', `${number(vehicle.wheelbase, 3)} m / ${escapeHTML(vehicle.tireSize)}`],
      ['Drive layout / transfer range', `${vehicle.driveModes.map(escapeHTML).join(', ')}${vehicle.lowRatio > 1 ? ` · ${number(vehicle.lowRatio, 2)}:1 low range` : ' · no low-range transfer case'}`],
      ['Transmission / final drive', `${escapeHTML(vehicle.transmissionName)} · ${vehicle.transmissionType === 'electric' ? `${number(vehicle.electric.frontReduction, 2)}:1 front / ${number(vehicle.electric.rearReduction, 2)}:1 rear` : `${number(vehicle.finalDrive, 3)}:1 axle ratio`}`],
      [vehicle.transmissionType === 'electric' ? 'Estimated motor envelope' : 'Engine curve', escapeHTML(vehicle.engine.curveStatus)],
      ['Suspension calibration', escapeHTML(vehicle.suspension.parameterStatus)],
      ['Pressure baseline', `${number(vehicle.stockPSIFront ?? vehicle.stockPSI)} PSI front / ${number(vehicle.stockPSIRear ?? vehicle.stockPSI)} PSI rear · ${escapeHTML(vehicle.pressureStatus)}`],
    ])}
    ${vehicle.geometryStatus ? `<p>${escapeHTML(vehicle.geometryStatus)}.</p>` : ''}
    ${vehicle.notes.map(note => `<p>${escapeHTML(note)}</p>`).join('')}
    ${vehicle.upgrade?.count ? `<h3>Workshop sources and assumptions</h3>${UPGRADE_SOURCES.map(source => `<div class="source-entry"><a href="${escapeHTML(source.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(source.title)} ↗</a><p>${escapeHTML(source.use)}</p></div>`).join('')}` : ''}
    <h3>How to read the evidence</h3>
    ${SOURCE_NOTES.map(note => `<p>${escapeHTML(note)}</p>`).join('')}
    <p>The Bronco uses the <strong>2.7 V6 automatic</strong> configuration documented for MY2024 Badlands. Its 330 hp / 415 lb-ft ratings assume premium fuel. The cited later-year Ford sheet and 2023 carry-over document are identified separately from the 2024 order guide and owner instructions.</p>
    ${orderedVehicles.map(candidate => `<h3>${escapeHTML(candidate.year)} ${escapeHTML(candidate.name)}${candidate.id === vehicle.id ? ' · selected' : ''}</h3>${candidate.sources.map(sourceEntry).join('')}`).join('')}`;
}

function art() {
  return `<h3>Vehicle models &amp; garage</h3>
    <p>The garage renders isolated views of the same original, reference-guided vehicle meshes used in the driving scene. There are no photographs or background vehicles in the garage. Paint choices apply to the model and are saved for each vehicle. The display models are pristine; the condition label describes retained driving damage.</p>
    <p>Body shapes, cabin details and tire patterns are visual approximations. Local dents, scratches, glazing damage and tire deformation are generated from simulation state. Paint changes retain existing driving damage.</p>
    <h3>Terrain and lighting assets</h3>
    <p>Photographic ground materials, pine textures, outdoor lighting and the imported stone model are from <a href="https://polyhaven.com/" target="_blank" rel="noopener noreferrer">Poly Haven</a>, published under <a href="https://polyhaven.com/license" target="_blank" rel="noopener noreferrer">CC0</a>. Exact asset names, authors and files are recorded in the <a href="./assets/terrain/SOURCES.md" target="_blank" rel="noopener noreferrer">terrain asset credits ↗</a>.</p>
    <p>Hardpack, loose gravel, grass, mud, sand and exposed rock have distinct surface detail. Tire paths darken and reshape softer ground as it compacts or churns. Nearby stones and plants add depth, and the mountain ranges frame the proving ground. Ruts, displaced berms, vegetation motion and collision marks are generated by the simulator.</p>
    <h3>Software</h3>
    <p>Three.js 0.180.0 and cannon-es 0.20.0 are used under the MIT license. Their license texts are included with the application.</p>`;
}

/** Render a self-contained guide pane. Vehicle IDs or catalogue records are accepted. */
export function getGuideHTML(topic = 'controls', selectedVehicle = VEHICLES[0]) {
  const vehicle = resolveVehicle(selectedVehicle);
  if (topic === 'technique') return `<h3>Snow basin and flotation tracks</h3><p>Choose <strong>Boreal Snow Basin</strong> in Terrain to reach the winter area north of the challenge park. The winding packed lane is firmer than the wind-loaded powder beside it. Impressions compact the snow during this run.</p><p>While stopped, open <strong>Workshop → Wheels or flotation tracks → Snow flotation tracks</strong> and install the build. Wrangler, Bronco and HUMMER support the generic four-module conversion; the Sprinter also needs its 4x4 drivetrain conversion. The Civic remains on tires. Tracks increase supported area and reduce pressure and sinkage, with extra mass, road drag and an estimated 43 km/h powered-speed limit. Return to Road wheels / tires to remove them.</p>` + technique(vehicle);
  switch (topic) {
    case 'technique': return technique(vehicle);
    case 'physics': return physics();
    case 'sources': return sources(vehicle);
    case 'art': return art();
    default: return controls(vehicle);
  }
}
